import { char, datetime, index, mysqlEnum, mysqlTable, primaryKey, varchar } from 'drizzle-orm/mysql-core';

/**
 * Drizzle schema — source for versioned migrations in `apps/api/drizzle`
 * (`npm run db:generate`). IDs are UUIDv4 generated by the domain; timestamps
 * are written by the domain in UTC with millisecond precision.
 */

const timestamps = {
  createdAt: datetime('created_at', { mode: 'date', fsp: 3 }).notNull(),
  updatedAt: datetime('updated_at', { mode: 'date', fsp: 3 }).notNull(),
};

export const users = mysqlTable('users', {
  id: char('id', { length: 36 }).primaryKey(),
  name: varchar('name', { length: 120 }).notNull(),
  email: varchar('email', { length: 254 }).notNull().unique('users_email_unique'),
  /** 11 digits, no separators. */
  cpf: char('cpf', { length: 11 }).notNull().unique('users_cpf_unique'),
  passwordHash: varchar('password_hash', { length: 255 }).notNull(),
  ...timestamps,
});

export const workspaces = mysqlTable('workspaces', {
  id: char('id', { length: 36 }).primaryKey(),
  name: varchar('name', { length: 150 }).notNull(),
  kind: mysqlEnum('kind', ['personal', 'demo', 'organization', 'lab']).notNull(),
  ...timestamps,
});

export const memberships = mysqlTable(
  'memberships',
  {
    userId: char('user_id', { length: 36 })
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    workspaceId: char('workspace_id', { length: 36 })
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    role: mysqlEnum('role', ['OWNER', 'ADMIN', 'ANALYST', 'VIEWER']).notNull(),
    createdAt: timestamps.createdAt,
  },
  (table) => [
    // One membership per (user, workspace): the composite key forbids duplicates.
    primaryKey({ name: 'memberships_user_workspace_pk', columns: [table.userId, table.workspaceId] }),
    index('memberships_workspace_idx').on(table.workspaceId),
  ],
);
